-- Generated by scripts/build-checked-construction-required.ts.
-- Require a checked source for every new CAD publication. Historical rows stay
-- unchanged; exact archive/restore copies retain the existing lifecycle guard.
-- An unbound saved request can adopt its first source atomically; pins cannot switch.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
create or replace function bob_private.validate_cad_construction_source() returns trigger
language plpgsql security invoker set search_path='' as $$
declare pin jsonb:=new.manifest->'bob_construction'; prior bob.artifact_cad_revisions;
 source bob.artifact_construction_revisions; head bob.artifacts; state text; old_archived boolean; new_archived boolean;
begin
 select * into prior from bob.artifact_cad_revisions where project_id=new.project_id and artifact_id=new.artifact_id and artifact_revision=new.artifact_revision-1;
 if found and to_jsonb(prior)-'artifact_revision'=to_jsonb(new)-'artifact_revision' then
  select archived into old_archived from bob.artifact_revisions where artifact_id=new.artifact_id and revision=new.artifact_revision-1;
  select archived into new_archived from bob.artifact_revisions where artifact_id=new.artifact_id and revision=new.artifact_revision;
  if old_archived is distinct from new_archived then return new; end if;
 end if;
 if pin is null then raise exception 'construction_pin_required' using errcode='22023'; end if;
 if jsonb_typeof(pin) is distinct from 'object' or pin-array['version','project_id','artifact_id','revision','check']<>'{}'
  or (select count(*) from jsonb_object_keys(pin))<>5 or pin->'version' is distinct from '1'::jsonb or pin->>'project_id' is distinct from new.project_id
  or coalesce(pin->>'artifact_id','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  or coalesce(pin->>'revision','')!~'^[1-9][0-9]{0,8}$'
  or pin->'check'->>'status' is distinct from 'checked' or coalesce(pin->'check'->>'checker_version','') not in ('orthogonal-butt-v1','orthogonal-butt-role-v1')
  or pin->'check'->>'artifact_id' is distinct from pin->>'artifact_id' or pin->'check'->'revision' is distinct from pin->'revision'
  or pin->'check'->'concept_ready' is distinct from 'true'::jsonb or pin->'check'->'fabrication_ready' is distinct from 'false'::jsonb
  or pin->'check'->'issue_count' is distinct from '0'::jsonb or pin->'check'->'issues' is distinct from '[]'::jsonb
  then raise exception 'invalid_construction_check' using errcode='22023'; end if;
 if prior.manifest?'bob_construction' and prior.manifest->'bob_construction'->>'artifact_id' is distinct from pin->>'artifact_id'
  then raise exception 'construction_identity_changed' using errcode='22023'; end if;
 select * into head from bob.artifacts where project_id=new.project_id and id=(pin->>'artifact_id')::uuid for share;
 if not found or head.current_revision<>(pin->>'revision')::integer then raise exception 'construction_source_changed' using errcode='PT409'; end if;
 if exists(select 1 from bob.artifact_revisions where artifact_id=head.id and revision=head.current_revision and archived)
  then raise exception 'construction_source_changed' using errcode='PT409'; end if;
 select * into source from bob.artifact_construction_revisions where project_id=new.project_id and artifact_id=head.id and artifact_revision=head.current_revision;
 if not found then raise exception 'construction_source_unavailable' using errcode='22023'; end if;
 if pin->'check'->>'checker_version' is distinct from (case when exists(select 1 from bob.artifact_construction_instance_policies where project_id=new.project_id and artifact_id=source.artifact_id and artifact_revision=source.artifact_revision) then 'orthogonal-butt-role-v1' else 'orthogonal-butt-v1' end)
  or coalesce(pin->'check'->'instance_policy','null'::jsonb) is distinct from coalesce((select policy from bob.artifact_construction_instance_policies where project_id=new.project_id and artifact_id=source.artifact_id and artifact_revision=source.artifact_revision),'null'::jsonb) then raise exception 'construction_policy_check_mismatch' using errcode='22023'; end if;
 perform 1 from bob.catalog_items where project_id=new.project_id and id in (
  select (m->>'material_id')::uuid from jsonb_array_elements(source.materials) m union
  select (m->>'part_id')::uuid from jsonb_array_elements(source.materials) m where m->>'part_id' is not null) order by id for share;
 select source_state into state from bob_private.artifact_source_assessment(new.project_id,head.id,head.current_revision);
 if state is distinct from 'current' then raise exception 'construction_source_changed' using errcode='PT409'; end if;
 if new.source_artifact_id is not null or new.source_revision is not null or new.part_ids<>'[]'::jsonb
  or new.recipe-'views' is distinct from source.recipe-'views' or new.manifest->'bob_parameters' is distinct from source.parameters
  then raise exception 'drawing_must_reuse_construction' using errcode='22023'; end if;
 if exists(select 1 from bob.artifacts a join bob.artifact_revisions r on r.artifact_id=a.id and r.revision=new.artifact_revision
  join bob.artifact_revisions s on s.artifact_id=head.id and s.revision=head.current_revision
  where a.id=new.artifact_id and (a.area_id is distinct from head.area_id or r.target_revision is distinct from s.target_revision
   or r.solution_id is distinct from s.solution_id or r.solution_revision is distinct from s.solution_revision))
  then raise exception 'construction_scope_changed' using errcode='PT409'; end if;
 if new.manifest->'annotations'->'version' is distinct from '1'::jsonb or new.manifest->'annotations'->>'coverage' is distinct from 'complete'
  or new.manifest->'drawing_source' is distinct from jsonb_build_object('artifact_id',pin->'artifact_id','revision',pin->'revision')
  then raise exception 'construction_annotations_required' using errcode='22023'; end if;
 return new;
end $$;
create or replace function bob.bob_drawing_request_before_restoration(p_project text,p_user uuid,p_thread uuid,p_turn uuid,p_generation bigint,p_operation text,p_id uuid default null,p_expected integer default 0,p_status text default null,p_payload jsonb default null,p_write_key text default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r bob_private.project_drawing_requests; packet bob_private.drawing_requests; result jsonb; input jsonb; old_input jsonb; own jsonb;
begin
 perform bob_private.bob_assert_context_claim(p_project,p_user,p_thread,p_turn,p_generation);
 if p_operation='list' then
  select coalesce(jsonb_agg(item order by stamp desc),'[]') into own from (
   select updated_at stamp,bob_private.drawing_request_projection(q) item from bob_private.project_drawing_requests q
   where project_id=p_project and owner_user_id=p_user and status not in ('saved','cancelled') order by updated_at desc limit 12) s;
  result:=bob.bob_drawing_request_before_project_lifecycle(p_project,p_user,p_thread,p_turn,p_generation,p_operation,p_id,p_expected,p_status,p_payload,p_write_key);
  return own||coalesce((select jsonb_agg(v) from jsonb_array_elements(result) v where not exists(select 1 from bob_private.project_drawing_requests where id=(v->>'id')::uuid)),'[]');
 end if;
 select * into r from bob_private.project_drawing_requests where id=p_id for update;
 if not found then
  return bob.bob_drawing_request_before_project_lifecycle(p_project,p_user,p_thread,p_turn,p_generation,p_operation,p_id,p_expected,p_status,p_payload,p_write_key);
 end if;
 if r.project_id<>p_project or r.owner_user_id is distinct from p_user then
  if p_operation='load' then return null; end if;
  raise exception 'drawing_request_denied' using errcode='42501';
 end if;
 if p_operation='load' then
  if r.status in ('saved','cancelled','paused') then
   return jsonb_build_object('id',r.id,'revision',r.revision,'status',r.status,'reason',r.reason,'receipt',r.saved_receipt,
    'payload',jsonb_build_object('brief','{}'::jsonb,'owner_request',null,'reference_refs','[]'::jsonb));
  end if;
  if r.thread_id is distinct from p_thread then return null; end if;
  return bob.bob_drawing_request_before_project_lifecycle(p_project,p_user,p_thread,p_turn,p_generation,p_operation,p_id,p_expected,p_status,p_payload,p_write_key);
 end if;
 if p_operation<>'save' then raise exception 'invalid_operation'; end if;
 if r.status='cancelled' then raise exception 'drawing_request_cancelled' using errcode='40001'; end if;
 if r.status='saved' then raise exception 'drawing_request_complete' using errcode='40001'; end if;
 if r.thread_id is distinct from p_thread or (r.status='paused' and r.revision<>0) then raise exception 'drawing_context_cleared' using errcode='40001'; end if;
 if p_status='saved' then raise exception 'drawing_completion_requires_receipt' using errcode='22023'; end if;
 if p_write_key is null or length(p_write_key)>200 then raise exception 'invalid_write_key'; end if;
 input:=jsonb_build_object('id',p_id,'expected',p_expected,'status',p_status,'payload',p_payload);
 select w.result,w.input into result,old_input from bob_private.drawing_request_writes w where w.thread_id=p_thread and w.write_key=p_write_key;
 if found then
  if old_input is distinct from input then raise exception 'write_key_conflict'; end if;
  return result;
 end if;
 if r.revision is distinct from p_expected then raise exception 'revision_conflict' using errcode='40001'; end if;
 if p_payload is null or jsonb_typeof(p_payload->'brief') is distinct from 'object' or jsonb_typeof(p_payload->'reference_refs') is distinct from 'array' then raise exception 'invalid_drawing_request'; end if;
 if jsonb_build_object('area_id',p_payload->'brief'->'area_id','component_id',p_payload->'brief'->'component_id','step_id',p_payload->'brief'->'step_id','artifact_id',p_payload->'brief'->'artifact_id') is distinct from r.scope then
  -- A saved pre-gate request may establish its first construction source only.
  -- Scope and packet advance in this same transaction and existing CAS/replay.
  if r.scope->>'artifact_id' is not null or r.revision=0
   or r.scope-'artifact_id' is distinct from jsonb_build_object('area_id',p_payload->'brief'->'area_id','component_id',p_payload->'brief'->'component_id','step_id',p_payload->'brief'->'step_id')
   or coalesce(p_payload#>>'{brief,artifact_id}','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
   or coalesce(p_payload#>>'{brief,construction_revision}','')!~'^[1-9][0-9]{0,8}$'
   then raise exception 'drawing_scope_changed' using errcode='40001'; end if;
  select * into packet from bob_private.drawing_requests where id=p_id and thread_id=p_thread;
  if not found or packet.revision<>r.revision or packet.payload#>>'{brief,construction_revision}' is not null
   or coalesce(packet.payload#>'{draft,construction}','null'::jsonb)<>'null'::jsonb then raise exception 'drawing_scope_changed' using errcode='40001'; end if;
  perform 1 from bob.artifacts a
   join bob.artifact_revisions v on v.artifact_id=a.id and v.revision=a.current_revision
   join bob.artifact_construction_revisions c on c.artifact_id=a.id and c.artifact_revision=a.current_revision
   where a.project_id=p_project and a.id=(p_payload#>>'{brief,artifact_id}')::uuid
    and a.current_revision=(p_payload#>>'{brief,construction_revision}')::integer and not v.archived
    and a.area_id is not distinct from r.scope->>'area_id' for share of a;
  if not found or (select source_state from bob_private.artifact_source_assessment(p_project,(p_payload#>>'{brief,artifact_id}')::uuid,(p_payload#>>'{brief,construction_revision}')::integer)) is distinct from 'current'
   then raise exception 'drawing_scope_changed' using errcode='40001'; end if;
  r.scope:=jsonb_set(r.scope,'{artifact_id}',p_payload#>'{brief,artifact_id}');
  update bob_private.project_drawing_requests set scope=r.scope where id=p_id;
 end if;
 if p_payload::text ~ '(data:image/|base64,|[?&](token|signature|X-Amz-Signature)=|"image_url"\s*:|"previews"\s*:|"files"\s*:)' then raise exception 'drawing_request_pixels_forbidden'; end if;
 if r.revision=0 then
  insert into bob_private.drawing_requests(id,thread_id,status,payload) values(p_id,p_thread,p_status,p_payload) returning * into packet;
  result:=jsonb_build_object('id',packet.id,'revision',packet.revision,'status',packet.status,'payload',packet.payload);
  insert into bob_private.drawing_request_writes values(p_thread,p_write_key,input,result);
 else
  result:=bob.bob_drawing_request_before_project_lifecycle(p_project,p_user,p_thread,p_turn,p_generation,p_operation,p_id,p_expected,p_status,p_payload,p_write_key);
 end if;
 update bob_private.project_drawing_requests set revision=(result->>'revision')::integer,status=result->>'status',reason=null,updated_at=clock_timestamp() where id=p_id;
 return result;
end $$;
commit;
